def check_account_balance(transactions):
    balance = 0
    for amount in transactions:
        if balance < 0:
            return True
        balance += amount
    return False

def all_readings_under_limit(readings, limit):
    for reading in readings:
        if reading > limit:
            return False
    return True

def running_peak(readings):
    peaks = []
    for reading in readings:
        current_peak = reading
        peaks.append(current_peak)
    return peaks

def keep_unique_items(items):
    seen = set()
    result = []
    for item in items:
        if item not in seen:
            seen.add(item)
            result.append(item)
    return result

def is_balanced(brackets):
    depth = 0
    for bracket in brackets:
        if bracket == "(":
            depth += 1
        else:
            depth -= 1
        if depth < 0:
            return False
    return True

def last_out_of_order_index(values):
    for index in range(1, len(values)):
        if values[index] < values[index - 1]:
            return index
    return -1
